style.css:
@-moz-document domain("roblox.com") {
body {
        background: url("https://i.imgur.com/d6fG6vU.jpeg") no-repeat center center fixed !important;
        background-size: cover !important;
        color: #e0e0ff !important;
        font-family: 'Segoe UI', sans-serif;
    }

    .navigation-container,
    .header {
        background-color: rgba(20, 20, 35, 0.8) !important;
        border-bottom: 1px solid #8888ff !important;
    }

    button, .btn-primary {
        background-color: #7aaaff !important;
        border: none !important;
        color: white !important;
    }

    button:hover, .btn-primary:hover {
        background-color: #aaccff !important;
    }

    .section, .content, .card-item {
        background-color: rgba(30, 30, 45, 0.9) !important;
        border: 1px solid #555577 !important;
        color: #e0e0ff !important;
    }

    a {
        color: #99ccff !important;
    }

    a:hover {
        color: #cce6ff !important;
    }

    .logo-container {
        display: none !important;
    }
}
